const UNIT = [
  "[Unit]",
  "Description=orders-api",
  "After=network-online.target",
  "",
  "[Service]",
  "User=app",
  "WorkingDirectory=/srv/orders",
  "ExecStart=/usr/bin/node /srv/orders/dist/server.js",
  "Restart=on-failure",
  "RestartSec=2",
  "StartLimitBurst=3",
  "StartLimitIntervalSec=60",
  "",
  "[Install]",
  "WantedBy=multi-user.target",
  "",
].join("\n");

function parseUnit(text) {
  const sections = {};
  let sec = null;
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    if (line.startsWith("[") && line.endsWith("]")) {
      sec = line.slice(1, -1);
      sections[sec] = {};
      continue;
    }
    const i = line.indexOf("=");
    if (i > 0 && sec) sections[sec][line.slice(0, i)] = line.slice(i + 1);
  }
  return sections;
}

const sec = parseUnit(UNIT);
const svc = sec.Service || {};
const unit = sec.Unit || {};
const inst = sec.Install || {};

const issues = [];
if (!svc.ExecStart) issues.push("missing_ExecStart");
if (!svc.User) issues.push("runs_as_root_by_default");
if (svc.User === "root") issues.push("explicit_root_user");
if (!["always", "on-failure"].includes(svc.Restart)) issues.push("weak_restart_policy");
if (!svc.RestartSec) issues.push("missing_RestartSec");
if (!(unit.After || "").includes("network-online.target")) issues.push("missing_network_ordering");
if (!inst.WantedBy) issues.push("not_enabled_on_boot");

console.log("sections=" + Object.keys(sec).join(","));
console.log("ExecStart=" + (svc.ExecStart || "-"));
console.log("User=" + (svc.User || "-") + " Restart=" + (svc.Restart || "-") + " RestartSec=" + (svc.RestartSec || "-"));
console.log("issues=" + issues.length + " [" + issues.join(",") + "]");

// 模拟：进程每 crashEverySec 崩溃一次，systemd 等待 RestartSec 后重启；
// StartLimitIntervalSec 窗口内启动次数超过 StartLimitBurst 则进入 start-limit-hit。
function simulate(crashEverySec, restartSec, burst, intervalSec) {
  const starts = [];
  let t = 0;
  let state = "running";
  let reason = "-";
  for (let step = 0; step < 10; step++) {
    starts.push(t);
    const recent = starts.filter(s => t - s < intervalSec).length;
    if (recent > burst) {
      state = "failed";
      reason = "start-limit-hit";
      starts.pop();
      break;
    }
    t += crashEverySec;
    t += restartSec;
    if (t >= 120) break;
  }
  return { starts, state, reason, t };
}

const r = simulate(10, 2, Number(svc.StartLimitBurst), Number(svc.StartLimitIntervalSec));
console.log("=== restart simulation ===");
console.log("start_ticks=" + r.starts.join(","));
console.log("starts_count=" + r.starts.length);
console.log("final_state=" + r.state + " reason=" + r.reason);
console.log("=== judgement ===");
console.log("unit_static_ok=" + (issues.length === 0));
console.log("restart_policy_is_on_failure=" + (svc.Restart === "on-failure"));
console.log("non_root_user=" + (Boolean(svc.User) && svc.User !== "root"));
console.log("enters_failed_after_burst=" + (r.state === "failed" && r.reason === "start-limit-hit"));
console.log("restart_count_before_failure=" + r.starts.length);
